// Openings take-off — door/window joinery lines and opening areas from the
// deterministic engine (scripts/drawing-ocr/quantity_core.py
// openings_takeoff: schedule sizes x instance counts) through the app's
// EXISTING path: import (parseAnalysisV1) -> recompute (measurementValidator
// via calculationAdvisory / lineEvidence) -> review -> Apply plan -> the real
// applyReviewPlan() write -> the persisted boq_line -> the CSV renderer.
// Only the Supabase client is mocked, as in quantityTakeoff.integration.test.ts.
//
// The fixture is generated by the engine from made-up inputs
// (openings_fixture() in scripts/drawing-ocr/test_quantity_core.py, which
// fails if it drifts). Synthetic data: this proves the contract and the
// workflow, not take-off accuracy on real drawings.
import { describe, it, expect, vi, beforeEach } from "vitest";

const boqLineStore = new Map<string, Record<string, unknown>>();
let nextId = 0;

vi.mock("@/integrations/supabase/client", () => ({
  supabase: {
    auth: { getUser: async () => ({ data: { user: { id: "user-1" } } }) },
    from: (table: string) => ({
      insert: (payload: Record<string, unknown>) => {
        const id = `new-line-${++nextId}`;
        const result = table === "boq_line" ? { data: { id }, error: null } : { error: null };
        if (table === "boq_line") boqLineStore.set(id, payload);
        return {
          select: () => ({ single: async () => result }),
          then: (onFulfilled: (v: unknown) => unknown) => Promise.resolve(result).then(onFulfilled),
        };
      },
      update: () => ({ eq: () => Promise.resolve({ error: null }) }),
      select: () => {
        const b = {
          eq: () => b, not: () => b,
          single: async () => (table === "boq" ? { data: { project_id: "project-1" }, error: null } : { data: null, error: null }),
          maybeSingle: async () => ({ data: null, error: null }),
          then: (resolve: (v: { data: unknown; error: null }) => void) => resolve({ data: [], error: null }),
        };
        return b;
      },
    }),
  },
}));

import fixture from "./__fixtures__/openingsTakeoffSynthetic.json";
import { parseAnalysisV1, type AnalysisItemV1 } from "./analysisSchemaV1";
import { validateItemCalculation, calculationAdvisoryText } from "./calculationAdvisory";
import { buildApplyPlan, applyReviewPlan } from "./applyReview";
import { evidenceForLine, type EvidenceItem } from "../lineEvidence";
import { REVIEW_VERIFIED_BASIS } from "../quantity";
import { buildBoqCsv, type CsvRow } from "../boqDsrDocument";
import type { StoredReviewItem } from "./reviewStore";

const parsed = parseAnalysisV1(JSON.stringify(fixture));
const items = parsed.analysis!.items;
const byKey = (k: string) => items.find((i) => i.key === k)!;
const stored = (id: string, ai: AnalysisItemV1, o: Partial<StoredReviewItem> = {}): StoredReviewItem => ({ id, ai, reviewStatus: "PENDING_REVIEW", ...o });

beforeEach(() => { boqLineStore.clear(); nextId = 0; });

describe("openings take-off output through import and recompute", () => {
  it("imports with no warnings; only fully resolved openings are MEASURED", () => {
    expect(parsed.ok).toBe(true);
    expect(parsed.warnings).toEqual([]);
    expect(items.map((i) => [i.key, i.aiStatus, i.quantity, i.unit])).toEqual([
      ["D1", "MEASURED", 3, "nos"],
      ["AREA:D1", "MEASURED", 5.67, "sqm"],
      ["W1", "PENDING", null, "nos"],
      ["AREA:W1", "PENDING", null, "sqm"],
      ["W2", "PENDING", null, "nos"],
      ["AREA:W2", "PENDING", null, "sqm"],
    ]);
  });

  it("the app recomputes an opening area from one opening's area and the count", () => {
    const a = byKey("AREA:D1");
    expect(a.calculationData?.formula).toBe("QUANTITY_PER_UNIT_TIMES_UNIT_COUNT");
    const v = validateItemCalculation(a);
    expect(v?.comparison?.outcome).toBe("EXACT_MATCH");
    expect(calculationAdvisoryText(v)).toBe("Arithmetic matches — not drawing verification.");
  });

  it("an unresolved count or size never becomes a number; the reviewer sees the bounds", () => {
    // W1: the count is unresolved upstream -> area candidates are one opening x each possible count
    expect(byKey("AREA:W1").candidates?.map((c) => c.value)).toEqual([7.2, 9]);
    // W2: two sizes printed -> each size x the resolved count; the joinery line keeps the count as a candidate
    expect(byKey("AREA:W2").candidates?.map((c) => c.value)).toEqual([1.08, 1.44]);
    expect(byKey("W2").candidates?.map((c) => c.value)).toEqual([2]);
    for (const k of ["W1", "AREA:W1", "W2", "AREA:W2"]) expect(byKey(k).calculationData).toBeUndefined();
  });
});

describe("openings take-off through review, Apply, the persisted line and export", () => {
  it("verified joinery and opening-area lines are written with their units and keys and export unchanged", async () => {
    const d1 = stored("ri-d1", byKey("D1"), { reviewStatus: "VERIFIED" });
    const a1 = stored("ri-a1", byKey("AREA:D1"), { reviewStatus: "VERIFIED" });
    const plan = buildApplyPlan([d1, a1], []);
    expect(plan.map((c) => c.classification)).toEqual(["NEW_LINE", "NEW_LINE"]);
    const res = await applyReviewPlan({ boqId: "boq-1", candidates: plan, selectedIds: new Set(["ri-d1", "ri-a1"]) });
    expect(res.appliedCount).toBe(2);

    const lines = [...boqLineStore.values()];
    const joinery = lines.find((l) => l.external_key === "D1")!;
    const area = lines.find((l) => l.external_key === "AREA:D1")!;
    expect(joinery).toMatchObject({ qty: 3, unit: "nos", quantity_status: "COUNTED", basis: REVIEW_VERIFIED_BASIS });
    expect(String(joinery.description)).toContain("900 x 2100 mm");
    expect(area).toMatchObject({ qty: 5.67, unit: "sqm", quantity_status: "MEASURED", basis: REVIEW_VERIFIED_BASIS });

    const ev = evidenceForLine({ external_key: "AREA:D1", qty: 5.67, unit: "sqm" },
      [{ id: "ri-a1", runId: "run-1", ai: a1.ai, reviewStatus: "VERIFIED" } satisfies EvidenceItem]);
    expect(ev.kind).toBe("linked");
    if (ev.kind === "linked") expect(ev.calculation?.advisory).toBe("Arithmetic matches — not drawing verification.");

    const rows: CsvRow[] = [joinery, area].map((l, i) => ({
      subhead: "1.00 Doors and windows", itemNo: `1.0${i + 1}`, code: null, spec: String(l.description), unit: String(l.unit), qty: Number(l.qty), rate: null,
    }));
    const csv = buildBoqCsv(rows, { boqName: "Test BOQ", generatedOn: "1 Jan 2026" }).split("\r\n");
    expect(csv[4]).toContain("nos");
    expect(csv[4]).toContain(",3,");
    expect(csv[5]).toContain("sqm");
    expect(csv[5]).toContain("5.67");
  });

  it("unresolved openings are never applied while pending review", () => {
    const pending = ["W1", "AREA:W1", "W2", "AREA:W2"].map((k, i) => stored(`ri-p${i}`, byKey(k)));
    expect(buildApplyPlan(pending, []).map((c) => c.classification)).toEqual(["NOT_ELIGIBLE", "NOT_ELIGIBLE", "NOT_ELIGIBLE", "NOT_ELIGIBLE"]);
  });
});
